use csv_util::to_csv_row;

#[test]
fn plain_fields_stay_bare() {
    let fields = vec!["a".to_string(), "b".to_string(), "c".to_string()];
    assert_eq!(to_csv_row(&fields), "a,b,c");
}

#[test]
fn comma_triggers_quoting() {
    let fields = vec!["a,b".to_string(), "c".to_string()];
    assert_eq!(to_csv_row(&fields), "\"a,b\",c");
}

#[test]
fn embedded_quote_is_doubled_and_quoted() {
    let fields = vec!["say \"hi\"".to_string()];
    assert_eq!(to_csv_row(&fields), "\"say \"\"hi\"\"\"");
}

#[test]
fn newline_triggers_quoting() {
    let fields = vec!["line1\nline2".to_string()];
    assert_eq!(to_csv_row(&fields), "\"line1\nline2\"");
}

#[test]
fn mixed_row() {
    let fields = vec!["plain".to_string(), "has,comma".to_string(), "has\"quote".to_string()];
    assert_eq!(to_csv_row(&fields), "plain,\"has,comma\",\"has\"\"quote\"");
}

